#!/usr/bin/env node
// Differential harness: compares /workspace/dataset/test14_executable against /output/test14.mjs
// Usage: node diff.mjs <corpus.json> [--verbose] [--max N]
// corpus.json: array of either ["a","b"] pairs or {argv:[...]} objects.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test14_executable';
const JS = '/output/test14.mjs';

const args = process.argv.slice(2);
const file = args.find((x) => !x.startsWith('--'));
const verbose = args.includes('--verbose');
const maxIdx = args.indexOf('--max');
const max = maxIdx >= 0 ? Number(args[maxIdx + 1]) : Infinity;

const raw = JSON.parse(readFileSync(file, 'utf8'));
const cases = raw.slice(0, max).map((c) => (Array.isArray(c) ? { argv: ['--a', c[0], '--b', c[1]] } : c));

function run(cmd, argv) {
  const r = spawnSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

function show(s) {
  return JSON.stringify(s);
}

function firstDiff(a, b) {
  const n = Math.min(a.length, b.length);
  let i = 0;
  while (i < n && a[i] === b[i]) i++;
  return i;
}

let pass = 0;
const fails = [];
for (let i = 0; i < cases.length; i++) {
  const { argv } = cases[i];
  const py = run([EXE], argv);
  const js = run(['node', JS], argv);
  const ok = py.out === js.out && py.code === js.code && py.err === js.err;
  if (ok) {
    pass++;
    continue;
  }
  const d = firstDiff(py.out, js.out);
  fails.push({ i, argv, py, js, at: d });
  if (verbose || fails.length <= 12) {
    console.log(`\n===== CASE ${i} FAIL =====`);
    console.log('argv:', argv.map(show).join(' '));
    if (py.code !== js.code) console.log(`exit: py=${py.code} js=${js.code}`);
    if (py.err !== js.err) console.log(`stderr:\n  py=${show(py.err)}\n  js=${show(js.err)}`);
    if (py.out !== js.out) {
      console.log(`stdout diverges at byte ${d}`);
      console.log('  ctx  :', show(py.out.slice(Math.max(0, d - 60), d)));
      console.log('  py-> :', show(py.out.slice(d, d + 120)));
      console.log('  js-> :', show(js.out.slice(d, d + 120)));
    }
  }
}

console.log(`\n${pass}/${cases.length} passed, ${fails.length} failed`);
if (fails.length) {
  console.log('failing indices:', fails.map((f) => f.i).join(','));
  process.exitCode = 1;
}

