/**
 * Character classification primitives.
 *
 * Every predicate here is implemented with plain code-point arithmetic (or
 * `Intl.Segmenter`, a built-in) so that the whole library stays free of
 * pattern-matching engines.
 */

const SPACE = 0x20;
const TAB = 0x09;
const LF = 0x0a;
const CR = 0x0d;
const VT = 0x0b;
const FF = 0x0c;

/** ASCII space or tab. */
export function isBlank(code) {
  return code === SPACE || code === TAB;
}

/** ASCII digit `0`-`9`. */
export function isDigit(code) {
  return code >= 0x30 && code <= 0x39;
}

/** ASCII hexadecimal digit. */
export function isHexDigit(code) {
  return isDigit(code) || (code >= 0x41 && code <= 0x46) || (code >= 0x61 && code <= 0x66);
}

/** ASCII letter. */
export function isAsciiAlpha(code) {
  return (code >= 0x41 && code <= 0x5a) || (code >= 0x61 && code <= 0x7a);
}

/** ASCII letter or digit. */
export function isAsciiAlnum(code) {
  return isAsciiAlpha(code) || isDigit(code);
}

/**
 * Mirrors Python's `\s` for `str` patterns: the ASCII whitespace set plus the
 * Unicode separators and a handful of control characters that Python's
 * `str.isspace()` accepts.
 */
const UNICODE_SPACES = new Set([
  0x1c, 0x1d, 0x1e, 0x1f, 0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isSpaceCode(code) {
  if (code === SPACE || code === TAB || code === LF || code === CR || code === VT || code === FF) {
    return true;
  }
  return code >= 0x1c && UNICODE_SPACES.has(code);
}

export function isSpaceChar(ch) {
  return ch !== undefined && ch !== '' && isSpaceCode(ch.codePointAt(0));
}

/*
 * Python's `\w` accepts `str.isalnum()` characters plus `_`. `Intl.Segmenter`
 * classifies exactly the alphanumeric set as "word like" (it excludes `_`,
 * which we add back), which gives us full Unicode fidelity — CJK, full-width
 * Latin and accented letters count as word characters while emoji and CJK
 * punctuation do not.
 */
let segmenter = null;
const wordCharCache = new Map();

function segmenterSaysWordLike(ch) {
  if (segmenter === null) segmenter = new Intl.Segmenter('en', { granularity: 'word' });
  const parts = [...segmenter.segment(ch)];
  return parts.length === 1 && parts[0].isWordLike === true;
}

/** Python `\w`: any alphanumeric character (Unicode aware) or `_`. */
export function isWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  const code = ch.codePointAt(0);
  if (code < 0x80) return isAsciiAlnum(code) || code === 0x5f;
  let cached = wordCharCache.get(ch);
  if (cached === undefined) {
    cached = segmenterSaysWordLike(ch);
    wordCharCache.set(ch, cached);
  }
  return cached;
}

/**
 * Word-character test against the code point that *ends* at `index` in `text`,
 * i.e. the Python lookbehind `(?<!\w)` applied at position `index`. Surrogate
 * pairs are treated as the single character they encode.
 */
export function isWordCharBefore(text, index) {
  if (index <= 0) return false;
  const prev = text.charCodeAt(index - 1);
  if (prev >= 0xdc00 && prev <= 0xdfff && index >= 2) {
    const lead = text.charCodeAt(index - 2);
    if (lead >= 0xd800 && lead <= 0xdbff) return isWordChar(text.slice(index - 2, index));
  }
  return isWordChar(text[index - 1]);
}

/**
 * Word-character test for the code point starting at `index`, i.e. the Python
 * lookahead `(?=\w)` applied at position `index`.
 */
export function isWordCharAt(text, index) {
  if (index < 0 || index >= text.length) return false;
  const code = text.charCodeAt(index);
  if (code >= 0xd800 && code <= 0xdbff && index + 1 < text.length) {
    const trail = text.charCodeAt(index + 1);
    if (trail >= 0xdc00 && trail <= 0xdfff) return isWordChar(text.slice(index, index + 2));
  }
  return isWordChar(text[index]);
}

export const CODES = { SPACE, TAB, LF, CR, VT, FF };

