/**
 * String scanning helpers.
 *
 * These are the primitives the parsers are built from: everything is index
 * arithmetic plus `indexOf`/`slice`, so no pattern-matching engine is involved.
 */

import { isSpaceCode, isBlank } from './chars.mjs';

/** Split a document into physical lines on `\n` (a literal separator). */
export function splitLines(text) {
  return text.split('\n');
}

export function joinLines(lines) {
  return lines.join('\n');
}

/**
 * Python's `str.expandtabs(tabsize)`: column aware, with the column counter
 * reset by `\n` and `\r`. Iterating by code point keeps astral characters from
 * counting as two columns.
 */
export function expandTabs(text, tabSize) {
  if (text.indexOf('\t') === -1) return text;
  let out = '';
  let column = 0;
  for (const ch of text) {
    if (ch === '\t') {
      if (tabSize > 0) {
        const incr = tabSize - (column % tabSize);
        column += incr;
        out += ' '.repeat(incr);
      }
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
      column += 1;
      out += ch;
    }
  }
  return out;
}

/** Index of the first non-whitespace character, or `text.length`. */
export function firstNonSpace(text, from = 0) {
  let i = from;
  while (i < text.length && isSpaceCode(text.charCodeAt(i))) i++;
  return i;
}

/** Index one past the last non-whitespace character. */
export function lastNonSpace(text, to = text.length) {
  let i = to;
  while (i > 0 && isSpaceCode(text.charCodeAt(i - 1))) i--;
  return i;
}

/** Python `str.lstrip()`. */
export function lstrip(text) {
  return text.slice(firstNonSpace(text));
}

/** Python `str.rstrip()`. */
export function rstrip(text) {
  return text.slice(0, lastNonSpace(text));
}

/** Python `str.strip()`. */
export function strip(text) {
  const start = firstNonSpace(text);
  if (start === text.length) return '';
  return text.slice(start, lastNonSpace(text));
}

/** True when the line holds nothing but whitespace. */
export function isBlankLine(line) {
  return firstNonSpace(line) === line.length;
}

/** Number of leading ASCII spaces (tabs are expanded before we ever see them). */
export function countLeadingSpaces(line) {
  let n = 0;
  while (n < line.length && line.charCodeAt(n) === 0x20) n++;
  return n;
}

/** Count of leading spaces *and* tabs. */
export function countLeadingBlanks(line) {
  let n = 0;
  while (n < line.length && isBlank(line.charCodeAt(n))) n++;
  return n;
}

/** Number of consecutive `ch` characters starting at `from`. */
export function countRun(text, from, ch) {
  let n = 0;
  while (from + n < text.length && text[from + n] === ch) n++;
  return n;
}

/** Number of consecutive `ch` characters ending at `to` (exclusive). */
export function countRunBack(text, to, ch) {
  let n = 0;
  while (to - n - 1 >= 0 && text[to - n - 1] === ch) n++;
  return n;
}

/** `text.startsWith(prefix, at)` — kept as a named helper for readability. */
export function matchAt(text, prefix, at) {
  return text.startsWith(prefix, at);
}

/** First index at or after `from` holding any character of `chars`. */
export function findAnyChar(text, chars, from = 0) {
  for (let i = from; i < text.length; i++) {
    if (chars.indexOf(text[i]) !== -1) return i;
  }
  return -1;
}

/** Remove up to `n` leading spaces from `line`. */
export function dedentLine(line, n) {
  let i = 0;
  while (i < n && i < line.length && line.charCodeAt(i) === 0x20) i++;
  return line.slice(i);
}

/**
 * Replace every occurrence of a literal substring. `String.replaceAll` with a
 * string needle performs no pattern compilation.
 */
export function replaceAllLiteral(text, needle, replacement) {
  if (needle === '' || text.indexOf(needle) === -1) return text;
  return text.split(needle).join(replacement);
}

