/**
 * A minimal element tree, modelled on the API surface the Markdown pipeline
 * actually uses: a tag, ordered attributes, `text`, `tail` and children.
 */

/**
 * Marks a string as "atomic": inline processors must leave it alone. Code spans
 * and code blocks produce atomic text.
 */
export class AtomicString {
  constructor(value) {
    this.value = value;
  }

  toString() {
    return this.value;
  }
}

export function atomic(value) {
  return new AtomicString(value);
}

export function isAtomic(text) {
  return text instanceof AtomicString;
}

/** The plain-string view of a `text`/`tail` slot. */
export function textValue(text) {
  if (text === null || text === undefined) return '';
  return text instanceof AtomicString ? text.value : text;
}

/** Truthiness test matching Python's `if elem.text:` (empty string is falsy). */
export function hasText(text) {
  return text !== null && text !== undefined && textValue(text) !== '';
}

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    this.attrib = new Map();
