/**
 * Shared constants and the raw-HTML stash.
 */

/** Sentinels used to fence off content that must survive later passes. */
export const STX = '';
export const ETX = '';

/** Placeholder wrapping a stashed raw-HTML fragment. */
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const HTML_PLACEHOLDER_SUFFIX = ETX;

/** Placeholder wrapping a node produced by an inline processor. */
export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const INLINE_PLACEHOLDER_SUFFIX = ETX;

/** Stand-in for a literal `&` that must not be escaped by the serializer. */
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;

export const TAB_LENGTH = 4;

/** Characters a backslash may escape. */
export const ESCAPED_CHARS = [
  '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!',
];

/**
 * Tags that may not be wrapped in a `<p>`, plus tags whose contents Markdown
 * should leave alone. Membership decides whether a raw-HTML run is lifted out
 * of the document as a block or left inline.
 */
export const BLOCK_LEVEL_ELEMENTS = [
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li', 'legend',
  'math', 'map', 'noscript', 'output', 'object', 'option', 'progress', 'script',
  'style', 'summary', 'tbody', 'td', 'textarea', 'tfoot', 'th', 'thead', 'tr', 'video',
];

const BLOCK_LEVEL_SET = new Set(BLOCK_LEVEL_ELEMENTS);

/** Strip trailing `/` characters (so `<br/>` reports as `br`). */
function rstripSlash(tag) {
  let end = tag.length;
  while (end > 0 && tag[end - 1] === '/') end--;
  return tag.slice(0, end);
}

export function isBlockLevel(tag) {
  if (typeof tag !== 'string') return false;
  return BLOCK_LEVEL_SET.has(rstripSlash(tag.toLowerCase()));
}

export function htmlPlaceholder(key) {
  return HTML_PLACEHOLDER_PREFIX + key + HTML_PLACEHOLDER_SUFFIX;
}

export function inlinePlaceholder(id) {
  return INLINE_PLACEHOLDER_PREFIX + id + INLINE_PLACEHOLDER_SUFFIX;
}

/** Holds raw HTML fragments lifted out of the document during parsing. */
export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = htmlPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  reset() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  getPlaceholder(key) {
    return htmlPlaceholder(key);
  }
}

