/**
 * XHTML serializer, matching the escaping and empty-element rules of the
 * reference implementation's default `xhtml` output format.
 */

import { textValue } from './element.mjs';
import { replaceAllLiteral } from '../text/scan.mjs';

/** Elements serialized as `<tag />` with no closing tag. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img', 'input',
  'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/** Elements whose text content is emitted verbatim. */
const RAW_TAGS = new Set(['script', 'style']);

/** Character data escaping: `&`, `<` and `>`. */
export function escapeCdata(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = replaceAllLiteral(out, '&', '&amp;');
  if (out.indexOf('<') !== -1) out = replaceAllLiteral(out, '<', '&lt;');
  if (out.indexOf('>') !== -1) out = replaceAllLiteral(out, '>', '&gt;');
  return out;
}

/** Attribute value escaping: `&`, `<`, `>` and `"`. */
export function escapeAttrib(text) {
  let out = escapeCdata(text);
  if (out.indexOf('"') !== -1) out = replaceAllLiteral(out, '"', '&quot;');
  return out;
}

function serializeElement(parts, el) {
  const tag = el.tag;
  parts.push('<' + tag);
  for (const [key, value] of el.attrib) {
    parts.push(' ' + key + '="' + escapeAttrib(value === null ? key : String(value)) + '"');
  }
  const lower = tag.toLowerCase();
  if (HTML_EMPTY.has(lower)) {
    parts.push(' />');
  } else {
    parts.push('>');
    const text = textValue(el.text);
    if (text !== '') {
      parts.push(RAW_TAGS.has(lower) ? text : escapeCdata(text));
    }
    for (const child of el.children) serializeElement(parts, child);
    parts.push('</' + tag + '>');
  }
  const tail = textValue(el.tail);
  if (tail !== '') parts.push(escapeCdata(tail));
}

/** Serialize an element (and its subtree) to an XHTML string. */
export function toXhtmlString(root) {
  const parts = [];
  serializeElement(parts, root);
  return parts.join('');
}

