/**
 * A tolerant HTML tokenizer that mirrors the event sequence of the reference
 * implementation's parser (the standard library `html.parser` in permissive
 * mode, with character references left as ordinary data).
 *
 * The tokenizer is a hand-written scanner: it walks the source with index
 * arithmetic only. Handlers receive both the semantic pieces (tag name,
 * attributes) and the verbatim source text, because the Markdown raw-HTML
 * extractor re-emits the original bytes.
 */

import { isAsciiAlpha, isSpaceCode } from '../../text/chars.mjs';

/** Elements whose content is opaque until the matching end tag. */
const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

const TAGNAME_STOP = '\t\n\r\f />�';

function isSpaceAt(text, i) {
  return i < text.length && isSpaceCode(text.charCodeAt(i));
}

function skipSpaces(text, i) {
  while (isSpaceAt(text, i)) i++;
  return i;
}

/** `tagfind_tolerant`: a tag name followed by whitespace or non-final slashes. */
function matchTagName(text, i) {
  if (i >= text.length || !isAsciiAlpha(text.charCodeAt(i))) return null;
  let j = i + 1;
  while (j < text.length && TAGNAME_STOP.indexOf(text[j]) === -1) j++;
  const name = text.slice(i, j);
  while (j < text.length) {
    if (isSpaceAt(text, j)) j++;
    else if (text[j] === '/' && !text.startsWith('/>', j)) j++;
    else break;
  }
  return { name, end: j };
}

/** Trailing `(?:\s|/(?!>))*` shared by the attribute and tag-name scanners. */
function skipSpaceOrLooseSlash(text, i) {
  let j = i;
  while (j < text.length) {
    if (isSpaceAt(text, j)) j++;
    else if (text[j] === '/' && !text.startsWith('/>', j)) j++;
    else break;
  }
  return j;
}

/**
 * `attrfind_tolerant`, anchored at `i`. The name may not start with
 * whitespace, `/` or `>`, and must be preceded by a quote, whitespace or `/`.
 */
function matchAttribute(text, i, tagStart) {
  if (i <= tagStart) return null;
  const prev = text[i - 1];
  if (!(prev === '"' || prev === "'" || prev === '/' || isSpaceCode(prev.codePointAt(0)))) return null;
  if (i >= text.length) return null;
  const first = text[i];
  if (first === '/' || first === '>' || isSpaceCode(first.codePointAt(0))) return null;

  let j = i + 1;
  while (j < text.length) {
    const ch = text[j];
    if (ch === '/' || ch === '>' || ch === '=' || isSpaceCode(ch.codePointAt(0))) break;
    j++;
  }
  const name = text.slice(i, j);
  let value = null;

  // `(\s*=+\s*(?:'[^']*'|"[^"]*"|(?!['"])[^>\s]*))?`
  const afterName = j;
  let k = skipSpaces(text, j);
  if (k < text.length && text[k] === '=') {
    while (k < text.length && text[k] === '=') k++;
    k = skipSpaces(text, k);
    if (k < text.length && (text[k] === "'" || text[k] === '"')) {
      const quote = text[k];
      const close = text.indexOf(quote, k + 1);
      if (close === -1) {
        j = afterName; // The quoted value never closes: no value group.
      } else {
        value = text.slice(k + 1, close);
        j = close + 1;
      }
    } else {
      const start = k;
      while (k < text.length && text[k] !== '>' && !isSpaceAt(text, k)) k++;
      value = text.slice(start, k);
      j = k;
    }
    if (j !== afterName) {
      // `(?:\s*,)*`
      for (;;) {
        const save = j;
        const t = skipSpaces(text, j);
        if (t < text.length && text[t] === ',') j = t + 1;
        else {
          j = save;
          break;
        }
      }
    }
  }

  return { name, value, end: skipSpaceOrLooseSlash(text, j) };
}

/** `locatestarttagend_tolerant`: locate where a start tag's attribute list ends. */
function locateStartTagEnd(text, i) {
  const tag = matchTagName(text, i + 1);
  if (tag === null) return -1;
  let j = tag.end;

  // Optional attribute section, introduced by `[\s/]*`.
  let k = j;
  while (k < text.length && (isSpaceAt(text, k) || text[k] === '/')) k++;
  for (;;) {
    const attr = matchAttribute(text, k, i);
    if (attr === null) break;
    k = attr.end;
  }
  if (k > j) j = k;

  return skipSpaces(text, j);
}

/** `check_for_whole_start_tag`: end index of a complete start tag, or -1. */
function checkForWholeStartTag(text, i) {
  const j = locateStartTagEnd(text, i);
  if (j < 0) return -1;
  const next = j < text.length ? text[j] : '';
  if (next === '>') return j + 1;
  if (next === '/') {
    if (text.startsWith('/>', j)) return j + 2;
    return -1;
  }
  if (next === '') return -1;
  if (isAsciiAlpha(next.charCodeAt(0)) || next === '=' ) return -1;
  return j > i ? j : i + 1;
}

/** `_scan_name` for marked sections. */
function scanDeclName(text, i) {
  if (i >= text.length) return null;
  if (!isAsciiAlpha(text.charCodeAt(i))) return null;
  let j = i + 1;
  const extra = '-_.';
  while (j < text.length) {
    const ch = text[j];
    const code = ch.charCodeAt(0);
    if (isAsciiAlpha(code) || (code >= 0x30 && code <= 0x39) || extra.indexOf(ch) !== -1) j++;
    else break;
  }
  const name = text.slice(i, j).toLowerCase();
  return { name, end: skipSpaces(text, j) };
}

/** Search for `--\s*>` at or after `from`; returns `[start, end]` or null. */
function findCommentClose(text, from) {
  let i = from;
  for (;;) {
    const at = text.indexOf('--', i);
    if (at === -1) return null;
    const after = skipSpaces(text, at + 2);
    if (after < text.length && text[after] === '>') return [at, after + 1];
    i = at + 1;
  }
}

/** Search for `]\s*]\s*>` (marked section close). */
function findMarkedSectionClose(text, from) {
  let i = from;
  for (;;) {
    const at = text.indexOf(']', i);
    if (at === -1) return null;
    let j = skipSpaces(text, at + 1);
    if (j < text.length && text[j] === ']') {
      j = skipSpaces(text, j + 1);
      if (j < text.length && text[j] === '>') return [at, j + 1];
    }
    i = at + 1;
  }
}

/** Search for `]\s*>` (Microsoft Office style marked section close). */
function findMsMarkedSectionClose(text, from) {
  let i = from;
  for (;;) {
    const at = text.indexOf(']', i);
    if (at === -1) return null;
    const j = skipSpaces(text, at + 1);
    if (j < text.length && text[j] === '>') return [at, j + 1];
    i = at + 1;
  }
}

/** Case-insensitive search for `</\s*<name>`, used to leave CDATA mode. */
function findCdataEnd(text, from, name) {
  const lower = text.toLowerCase();
  let i = from;
  for (;;) {
    const at = lower.indexOf('</', i);
    if (at === -1) return -1;
    const j = skipSpaces(text, at + 2);
    if (lower.startsWith(name, j)) return at;
    i = at + 1;
  }
}

/**
 * Drives the scan. `handler` receives, for each construct, the verbatim source
 * text and the absolute index it starts at.
 */
export class HtmlTokenizer {
  constructor(handler) {
    this.handler = handler;
    this.cdataElem = null;
  }

  parse(text) {
    const h = this.handler;
    const n = text.length;
    let i = 0;

    while (i < n) {
      let j;
      if (this.cdataElem !== null) {
        const found = findCdataEnd(text, i, this.cdataElem);
        j = found === -1 ? n : found;
      } else {
        const found = text.indexOf('<', i);
        j = found === -1 ? n : found;
      }
      if (i < j) h.onData(text.slice(i, j), i);
      i = j;
      if (i === n) break;

      let k;
      if (text.startsWith('</', i)) {
        k = this.parseEndTag(text, i);
      } else if (i + 1 < n && isAsciiAlpha(text.charCodeAt(i + 1))) {
        k = this.parseStartTag(text, i);
      } else if (text.startsWith('<!--', i)) {
        k = this.parseComment(text, i);
      } else if (text.startsWith('<?', i)) {
        k = this.parsePi(text, i);
      } else if (text.startsWith('<!', i)) {
        k = this.parseHtmlDeclaration(text, i);
      } else {
        h.onData('<', i);
        k = i + 1;
      }

      if (k < 0) {
        k = text.indexOf('<', i + 1);
        if (k < 0) {
          k = text.indexOf('>', i + 1);
          k = k < 0 ? i + 1 : k + 1;
        }
        h.onData(text.slice(i, k), i);
      }
      i = k;
    }
  }

  parseStartTag(text, i) {
    const endpos = checkForWholeStartTag(text, i);
    if (endpos < 0) return endpos;
    const rawText = text.slice(i, endpos);

    const tagMatch = matchTagName(text, i + 1);
    const tag = tagMatch.name.toLowerCase();
    let k = tagMatch.end;
    const attrs = [];
    while (k < endpos) {
      const attr = matchAttribute(text, k, i);
      if (attr === null) break;
      attrs.push([attr.name.toLowerCase(), attr.value]);
      k = attr.end;
    }

    let tail = text.slice(k, endpos);
    tail = tail.slice(0, tail.length).trim();
    if (tail !== '>' && tail !== '/>') {
      this.handler.onData(rawText, i);
      return endpos;
    }
    if (tail.endsWith('/>')) {
      this.handler.onStartEndTag(tag, attrs, rawText, i);
    } else {
      this.handler.onStartTag(tag, attrs, rawText, i);
      if (CDATA_CONTENT_ELEMENTS.has(tag) && this.cdataElem === null) {
        this.cdataElem = this.handler.keepsCdataMode(tag) ? tag : null;
      }
    }
    return endpos;
  }

  parseEndTag(text, i) {
    const gt = text.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;

    const wellFormed = this.matchEndTagFind(text, i);
    if (wellFormed === null) {
      if (this.cdataElem !== null) {
        this.handler.onData(text.slice(i, gtpos), i);
        return gtpos;
      }
      const nameMatch = matchTagName(text, i + 2);
      if (nameMatch === null) {
        if (text.startsWith('</>', i)) return i + 3;
        return this.parseBogusComment(text, i);
      }
      const tagName = nameMatch.name.toLowerCase();
      const close = text.indexOf('>', nameMatch.end);
      this.handler.onEndTag(tagName, null, i);
      return close + 1;
    }

    const elem = wellFormed.name.toLowerCase();
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.handler.onData(text.slice(i, gtpos), i);
      return gtpos;
    }
    this.handler.onEndTag(elem, text.slice(i, wellFormed.end), i);
    this.cdataElem = null;
    return wellFormed.end;
  }

  /** `endtagfind`: `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>` anchored at `i`. */
  matchEndTagFind(text, i) {
    let j = skipSpaces(text, i + 2);
    if (j >= text.length || !isAsciiAlpha(text.charCodeAt(j))) return null;
    const start = j;
    j++;
    const extra = '-.:_';
    while (j < text.length) {
      const ch = text[j];
      const code = ch.charCodeAt(0);
      if (isAsciiAlpha(code) || (code >= 0x30 && code <= 0x39) || extra.indexOf(ch) !== -1) j++;
      else break;
    }
    const name = text.slice(start, j);
    j = skipSpaces(text, j);
    if (j < text.length && text[j] === '>') return { name, end: j + 1 };
    return null;
  }

  parseComment(text, i) {
    const close = findCommentClose(text, i + 4);
    if (close === null) return -1;
    this.handler.onComment(text.slice(i + 4, close[0]), i);
    return close[1];
  }

  parseBogusComment(text, i) {
    const pos = text.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.handler.onComment(text.slice(i + 2, pos), i);
    return pos + 1;
  }

  parsePi(text, i) {
    const close = text.indexOf('>', i + 2);
    if (close === -1) return -1;
    this.handler.onPi(text.slice(i + 2, close), i);
    return close + 1;
  }

  parseHtmlDeclaration(text, i) {
    if (text.startsWith('<!--', i)) return this.parseComment(text, i);
    if (text.startsWith('<![', i)) return this.parseMarkedSection(text, i);
    if (text.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = text.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.handler.onDecl(text.slice(i + 2, gt), i);
      return gt + 1;
    }
    return this.parseBogusComment(text, i);
  }

  parseMarkedSection(text, i) {
    const scanned = scanDeclName(text, i + 3);
    if (scanned === null) return -1;
    let close;
    if (['temp', 'cdata', 'ignore', 'include', 'rcdata'].indexOf(scanned.name) !== -1) {
      close = findMarkedSectionClose(text, i + 3);
    } else if (['if', 'else', 'endif'].indexOf(scanned.name) !== -1) {
      close = findMsMarkedSectionClose(text, i + 3);
    } else {
      close = null;
    }
    if (close === null) return -1;
    this.handler.onUnknownDecl(text.slice(i + 3, close[0]), i);
    return close[1];
  }
}

