import { readFileSync, writeFileSync } from 'node:fs';

const file = '/output/lib/markdown/html/tokenizer.mjs';
let s = readFileSync(file, 'utf8');

const before = "const TAGNAME_STOP = '\\t\\n\\r\\f />" + String.fromCharCode(0) + "';";
const after = [
  '/** `[^\\t\\n\\r\\f />\\x00]` — the characters that terminate a tag name. */',
  'const TAGNAME_STOP_CODES = new Set([0x09, 0x0a, 0x0d, 0x0c, 0x20, 0x2f, 0x3e, 0x00]);',
  '',
  'function isTagNameStop(text, i) {',
  '  return TAGNAME_STOP_CODES.has(text.charCodeAt(i));',
  '}',
].join('\n');

if (!s.includes(before)) {
  console.error('anchor not found');
  process.exit(1);
}
s = s.split(before).join(after);
s = s.split('while (j < text.length && TAGNAME_STOP.indexOf(text[j]) === -1) j++;')
  .join('while (j < text.length && !isTagNameStop(text, j)) j++;');
writeFileSync(file, s);
console.log('patched; raw NULs remaining:', [...s].filter((c) => c === '\x00').length);

