/**
 * Lifts raw HTML out of the document before block parsing.
 *
 * A block-level tag that begins a line starts a "raw" run which continues until
 * its matching close tag; the whole run is stashed verbatim and replaced by a
 * placeholder. Inline-level tags are left in place for the inline processor to
 * pick up later.
 */

import { HtmlTokenizer } from './tokenizer.mjs';
import { isBlockLevel } from '../util.mjs';
import { isBlankLine, splitLines } from '../../text/scan.mjs';

/** Block tags that never have content of their own. */
const EMPTY_TAGS = new Set(['hr']);

/** `^([ ]*\n){2}` — two consecutive lines holding nothing but spaces. */
function startsWithBlankLine(text, from) {
  let i = from;
  for (let line = 0; line < 2; line++) {
    while (i < text.length && text[i] === ' ') i++;
    if (i >= text.length || text[i] !== '\n') return false;
    i++;
  }
  return true;
}

export class HtmlExtractor {
  constructor(stash) {
    this.stash = stash;
    this.source = '';
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this.cache = [];
    this.cleandoc = [];
    this.tokenizer = new HtmlTokenizer(this);
  }

  /** Extract from `source`, returning the document with placeholders. */
  run(source) {
    this.source = source;
    this.tokenizer.parse(source);
    if (this.cache.length) {
      this.cleandoc.push(this.stash.store(this.cache.join('')));
      this.cache = [];
    }
    return this.cleandoc.join('');
  }

  /** Index of the first character of the line containing `index`. */
  lineStart(index) {
    const nl = this.source.lastIndexOf('\n', index - 1);
    return nl === -1 ? 0 : nl + 1;
  }

  /** True at column 0, or within three columns of whitespace-only indent. */
  atLineStart(index) {
    const start = this.lineStart(index);
    const column = index - start;
    if (column === 0) return true;
    if (column > 3) return false;
    return isBlankLine(this.source.slice(start, index));
  }

  // --- Tokenizer handlers -------------------------------------------------

  keepsCdataMode() {
    // A `script`/`style` start tag outside a raw block is presumably standalone
    // (for instance inside a code span), so opaque-content mode is not entered.
    return this.inraw;
  }

  onData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this.cache.push(data);
    else this.cleandoc.push(data);
  }

  onStartTag(tag, attrs, rawText, index) {
    if (EMPTY_TAGS.has(tag)) {
      this.handleEmptyTag(rawText, index, true);
      return;
    }
    if (isBlockLevel(tag) && (this.intail || (this.atLineStart(index) && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    if (this.inraw) {
      this.stack.push(tag);
      this.cache.push(rawText);
    } else {
      this.cleandoc.push(rawText);
    }
  }

  onStartEndTag(tag, attrs, rawText, index) {
    this.handleEmptyTag(rawText, index, isBlockLevel(tag));
  }

  onEndTag(tag, rawText, index) {
    const text = this.endTagText(tag, rawText, index);
    if (this.inraw) {
      this.cache.push(text);
      if (this.stack.indexOf(tag) !== -1) {
        while (this.stack.length) {
          if (this.stack.pop() === tag) break;
        }
      }
      if (this.stack.length === 0) {
        if (startsWithBlankLine(this.source, index + text.length)) {
          this.cache.push('\n');
        } else {
          this.intail = true;
        }
        this.inraw = false;
        this.cleandoc.push(this.stash.store(this.cache.join('')));
        this.cleandoc.push('\n\n');
        this.cache = [];
      }
    } else {
      this.cleandoc.push(text);
    }
  }

  onComment(data, index) {
    this.handleEmptyTag('<!--' + data + '-->', index, true);
  }

  onDecl(data, index) {
    this.handleEmptyTag('<!' + data + '>', index, true);
  }

  onPi(data, index) {
    this.handleEmptyTag('<?' + data + '>', index, true);
  }

  onUnknownDecl(data, index) {
    this.handleEmptyTag('<![' + data + ']]>', index, true);
  }

  /**
   * `</tag>` as it appears in the source when it is recognizable, otherwise a
   * well-formed lowercase reconstruction.
   */
  endTagText(tag, rawText, index) {
    if (rawText !== null && rawText !== undefined) {
      const inner = rawText.slice(2, rawText.length - 1);
      let start = 0;
      while (start < inner.length && inner[start] === ' ') start++;
      let end = inner.length;
      while (end > start && inner[end - 1] === ' ') end--;
      if (inner.slice(start, end).toLowerCase() === tag) return rawText;
    }
    return '</' + tag + '>';
  }

  handleEmptyTag(data, index, isBlock) {
    if (this.inraw || this.intail) {
      this.cache.push(data);
      return;
    }
    if (this.atLineStart(index) && isBlock) {
      let payload = data;
      if (startsWithBlankLine(this.source, index + data.length)) {
        payload += '\n';
      } else {
        this.intail = true;
      }
      const previous = this.cleandoc.length ? this.cleandoc.pop() : '';
      if (!previous.endsWith('\n\n') && previous.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(previous);
      this.cleandoc.push(this.stash.store(payload));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(data);
    }
  }
}

/** Preprocessor entry point: lines in, lines out. */
export function htmlBlockPreprocessor(lines, stash) {
  const extractor = new HtmlExtractor(stash);
  return splitLines(extractor.run(lines.join('\n')));
}

