/**
 * Base class for block processors.
 *
 * A processor is asked, in registry order, whether it recognizes the next block
 * (`test`) and if so is handed the whole block list (`run`) so it can consume
 * one block and push back any leftovers.
 */

import { isBlankLine, splitLines, strip } from '../../text/scan.mjs';

export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.tabLength;
  }

  /** Last child of `parent`, or `null`. */
  lastChild(parent) {
    return parent.length ? parent.children[parent.length - 1] : null;
  }

  /**
   * Strip one indent level from the front of each line, stopping at the first
   * line that is neither indented nor blank. Returns `[detabbed, rest]`.
   */
  detab(text, length = this.tabLength) {
    const indent = ' '.repeat(length);
    const lines = splitLines(text);
    const kept = [];
    for (const line of lines) {
      if (line.startsWith(indent)) kept.push(line.slice(length));
      else if (isBlankLine(line)) kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(kept.length).join('\n')];
  }

  /** Strip `level` indent levels where present, leaving dedented lines alone. */
  looseDetab(text, level = 1) {
    const indent = ' '.repeat(this.tabLength * level);
    const lines = splitLines(text);
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].startsWith(indent)) lines[i] = lines[i].slice(indent.length);
    }
    return lines.join('\n');
  }

  /** Convenience: is the block non-blank? */
  static hasContent(block) {
    return strip(block) !== '';
  }
}

