/**
 * The block parser: splits a document on blank lines and hands each block to
 * the first registered processor that claims it.
 */

import { Element } from '../../dom/element.mjs';
import { splitLines } from '../../text/scan.mjs';

/** A stack of parser states (`list`, `looselist`, `detabbed`, `blockquote`). */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isState(state) {
    return this.stack.length ? this.stack[this.stack.length - 1] === state : false;
  }
}

export class BlockParser {
  constructor(md) {
    this.md = md;
    this.tabLength = md.tabLength;
    this.blockprocessors = [];
    this.state = new State();
    this.root = null;
  }

  /** Register a processor; higher priority runs first. */
  register(processor, name, priority) {
    this.blockprocessors.push({ processor, name, priority });
    this.blockprocessors.sort((a, b) => b.priority - a.priority);
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  /** Split `text` on blank lines and parse the resulting blocks. */
  parseChunk(parent, text) {
