  constructor(md) {
    this.md = md;
    this.tabLength = md.tabLength;
    this.blockprocessors = [];
    this.state = new State();
    this.root = null;
  }

  /** Register a processor; higher priority runs first. */
  register(processor, name, priority) {
    this.blockprocessors.push({ processor, name, priority });
    this.blockprocessors.sort((a, b) => b.priority - a.priority);
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  /** Split `text` on blank lines and parse the resulting blocks. */
  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length) {
      for (const entry of this.blockprocessors) {
        if (entry.processor.test(parent, blocks[0])) {
          if (entry.processor.run(parent, blocks) !== false) break;
        }
      }
    }
  }
}

export { splitLines };

