/**
 * ATX (`# Heading`) and Setext (`Heading` / `=====`) headers.
 *
 * The ATX scanner reproduces the reference pattern
 * `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)` by hand: a lazy body that stops
 * as early as a run of optional trailing hashes can reach the end of the line,
 * with a backslash always binding the character that follows it.
 */

import { BlockProcessor } from './base.mjs';
import { Element } from '../../dom/element.mjs';
import { countRun, splitLines, strip } from '../../text/scan.mjs';

/** `#*(?:\n|$)` anchored at `at`; returns the end of the match or -1. */
function matchHashTail(block, at) {
  const hashes = countRun(block, at, '#');
  for (let take = hashes; take >= 0; take--) {
    const j = at + take;
    if (j === block.length) return j;
    if (block[j] === '\n') return j + 1;
  }
  return -1;
}

/**
 * Leftmost ATX header in `block`. Returns `{start, end, level, header}` where
 * `start` includes the preceding newline (if any), mirroring the reference
 * pattern's leading `(?:^|\n)`.
 */
export function searchHashHeader(block) {
  let lineStart = 0;
  for (;;) {
    const matchStart = lineStart === 0 ? 0 : lineStart - 1;
    const hashes = countRun(block, lineStart, '#');
    for (let level = Math.min(6, hashes); level >= 1; level--) {
      const bodyStart = lineStart + level;
      let j = bodyStart;
      for (;;) {
        const end = matchHashTail(block, j);
        if (end !== -1) {
          return { start: matchStart, end, level, header: block.slice(bodyStart, j) };
        }
        if (j >= block.length) break;
        if (block[j] === '\\') {
          // `\\.` — a backslash must be followed by a non-newline character.
          if (j + 1 >= block.length || block[j + 1] === '\n') break;
          j += 2;
        } else {
          j += 1;
        }
      }
    }
    const nl = block.indexOf('\n', lineStart);
    if (nl === -1) return null;
    lineStart = nl + 1;
  }
}

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return searchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = searchHashHeader(block);
    if (m === null) return;
    const before = block.slice(0, m.start);
    const after = block.slice(m.end);
    if (before !== '') this.parser.parseBlocks(parent, [before]);
    const h = new Element('h' + m.level);
    parent.append(h);
    h.text = strip(m.header);
    if (after !== '') blocks.unshift(after);
  }
}

/** `^.*?\n[=-]+[ ]*(\n|$)` anchored at the start of the block. */
export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return false;
  let i = nl + 1;
  const runStart = i;
  while (i < block.length && (block[i] === '=' || block[i] === '-')) i++;
  if (i === runStart) return false;
  while (i < block.length && block[i] === ' ') i++;
  return i === block.length || block[i] === '\n';
}

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block);
  }

  run(parent, blocks) {
    const lines = splitLines(blocks.shift());
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = new Element('h' + level);
    parent.append(h);
    h.text = strip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

