/**
 * Horizontal rules: `---`, `___` or `***`, optionally spaced out, on a line of
 * their own (up to three leading spaces).
 */

import { BlockProcessor } from './base.mjs';
import { Element } from '../../dom/element.mjs';
import { rstrip } from '../../text/scan.mjs';

const RULE_CHARS = '-_*';

/**
 * `^[ ]{0,3}((-+[ ]{0,2}){3,}|(_+[ ]{0,2}){3,}|(\*+[ ]{0,2}){3,})[ ]*$`
 *
 * Equivalently: at most three leading spaces, then only one kind of rule
 * character and spaces, with interior space runs of at most two, and at least
 * three rule characters in total.
 */
function isRuleLine(line) {
  let lead = 0;
  while (lead < line.length && line[lead] === ' ') lead++;
  if (lead > 3 || lead === line.length) return false;
  const ch = line[lead];
  if (RULE_CHARS.indexOf(ch) === -1) return false;

  let count = 0;
  let i = lead;
  while (i < line.length) {
    if (line[i] === ch) {
      count++;
      i++;
    } else if (line[i] === ' ') {
      let spaces = 0;
      while (i < line.length && line[i] === ' ') {
        spaces++;
        i++;
      }
      // Interior space runs belong to a `[ ]{0,2}` group; a trailing run is
      // absorbed by the final `[ ]*`.
      if (i < line.length && spaces > 2) return false;
    } else {
      return false;
    }
  }
  return count >= 3;
}

/** Leftmost rule line in `block`, as `{start, end}` line bounds. */
export function searchRule(block) {
  let lineStart = 0;
  for (;;) {
    let lineEnd = block.indexOf('\n', lineStart);
    if (lineEnd === -1) lineEnd = block.length;
    if (isRuleLine(block.slice(lineStart, lineEnd))) return { start: lineStart, end: lineEnd };
    if (lineEnd === block.length) return null;
    lineStart = lineEnd + 1;
  }
}

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = searchRule(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    let prelines = block.slice(0, match.start);
    // `rstrip('\n')` — only newlines are removed.
    let end = prelines.length;
    while (end > 0 && prelines[end - 1] === '\n') end--;
    prelines = prelines.slice(0, end);
    if (prelines !== '') this.parser.parseBlocks(parent, [prelines]);

    parent.append(new Element('hr'));

    let postlines = block.slice(match.end);
    let start = 0;
    while (start < postlines.length && postlines[start] === '\n') start++;
    postlines = postlines.slice(start);
    if (postlines !== '') blocks.unshift(postlines);
  }
}

export { rstrip };

