/**
 * Ordered and unordered lists.
 *
 * A block whose first line looks like a list item is split into items; each
 * item is then parsed on its own with the `li` as parent. Nested items are
 * recognized by their indent and handed to the previous item.
 */

import { BlockProcessor } from './base.mjs';
import { Element, textValue, hasText } from '../../dom/element.mjs';
import { countLeadingSpaces, isDigit, splitLines } from './listHelpers.mjs';

/**
 * Match a list-item line.
 *
 * `kinds` selects which markers are accepted: `'ordered'` for `1.`, `'bullet'`
 * for `*`, `+` and `-`, `'both'` for either. The indent must fall within
 * `[minIndent, maxIndent]`.
 */
export function matchItemLine(line, kinds, minIndent, maxIndent) {
  const indent = countLeadingSpaces(line);
  if (indent < minIndent || indent > maxIndent) return null;
  let i = indent;
  let marker = '';
  if (kinds !== 'bullet' && i < line.length && isDigit(line.charCodeAt(i))) {
    const start = i;
    while (i < line.length && isDigit(line.charCodeAt(i))) i++;
    if (i >= line.length || line[i] !== '.') return null;
    i++;
    marker = line.slice(start, i);
  } else if (kinds !== 'ordered' && i < line.length && '*+-'.indexOf(line[i]) !== -1) {
    marker = line[i];
    i++;
  } else {
    return null;
  }
  // `[ ]+` — at least one space must follow the marker.
  const spaceStart = i;
  while (i < line.length && line[i] === ' ') i++;
  if (i === spaceStart) return null;
  return { marker, content: line.slice(i), indent };
}

export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.tag = 'ol';
    this.startsWith = '1';
    this.lazyOl = true;
    this.siblingTags = ['ol', 'ul'];
    this.itemKind = 'ordered';
  }

  /** First line of the block must be an item of this list's own kind. */
  test(parent, block) {
    const firstLine = splitLines(block)[0];
    return matchItemLine(firstLine, this.itemKind, 0, this.tabLength - 1) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.siblingTags.indexOf(sibling.tag) !== -1) {
      lst = sibling;
      const last = lst.children[lst.length - 1];
      if (hasText(last.text)) {
        const p = new Element('p');
        p.text = last.text;
        last.text = '';
        last.insert(0, p);
      }
      const lch = this.lastChild(last);
      if (lch !== null && hasText(lch.tail)) {
        const p = new Element('p');
        last.append(p);
        let tail = textValue(lch.tail);
        let start = 0;
        while (start < tail.length && ' \t\n\r\f\v'.indexOf(tail[start]) !== -1) start++;
        p.text = tail.slice(start);
        lch.tail = '';
      }
      const li = new Element('li');
      lst.append(li);
      this.parser.state.set('looselist');
      const firstitem = items.shift();
      this.parser.parseBlocks(li, [firstitem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      lst = parent;
    } else {
      lst = new Element(this.tag);
      parent.append(lst);
      if (!this.lazyOl && this.startsWith !== '1') lst.set('start', this.startsWith);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.children[lst.length - 1], [item]);
      } else {
        const li = new Element('li');
        lst.append(li);
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
  }

  /** Break a block into the text of each list item. */
  getItems(block) {
    const items = [];
    for (const line of splitLines(block)) {
      const child = matchItemLine(line, 'both', 0, this.tabLength - 1);
      if (child !== null) {
        if (!items.length && this.tag === 'ol') {
          let digits = '';
          for (const ch of child.marker) {
            if (isDigit(ch.charCodeAt(0))) digits += ch;
            else break;
          }
          this.startsWith = digits;
        }
        items.push(child.content);
      } else if (matchItemLine(line, 'both', this.tabLength, this.tabLength * 2 - 1) !== null) {
        if (items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = items[items.length - 1] + '\n' + line;
        } else {
          items.push(line);
        }
      } else {
        items[items.length - 1] = items[items.length - 1] + '\n' + line;
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.tag = 'ul';
