/**
 * Children of list items: a block indented by one tab level belongs to the
 * preceding list item rather than starting a code block.
 */

import { BlockProcessor } from './base.mjs';
import { Element, hasText } from '../../dom/element.mjs';

const ITEM_TYPES = ['li'];
const LIST_TYPES = ['ul', 'ol'];

export class ListIndentProcessor extends BlockProcessor {
  test(parent, block) {
    if (!block.startsWith(' '.repeat(this.tabLength))) return false;
    if (this.parser.state.isState('detabbed')) return false;
    if (ITEM_TYPES.indexOf(parent.tag) !== -1) return true;
    const last = parent.length ? parent.children[parent.length - 1] : null;
    return last !== null && LIST_TYPES.indexOf(last.tag) !== -1;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (ITEM_TYPES.indexOf(parent.tag) !== -1) {
      const last = parent.length ? parent.children[parent.length - 1] : null;
      if (last !== null && LIST_TYPES.indexOf(last.tag) !== -1) {
        this.parser.parseBlocks(last, [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (ITEM_TYPES.indexOf(sibling.tag) !== -1) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && ITEM_TYPES.indexOf(sibling.children[sibling.length - 1].tag) !== -1) {
      const li = sibling.children[sibling.length - 1];
      if (hasText(li.text)) {
        const p = new Element('p');
        p.text = li.text;
        li.text = '';
        li.insert(0, p);
      }
      this.parser.parseChunk(li, block);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
  }

  createItem(parent, block) {
    const li = new Element('li');
    parent.append(li);
    this.parser.parseBlocks(li, [block]);
  }

  /** Walk down the tree looking for the list level matching the block indent. */
  getLevel(parent, block) {
    // `^(([ ]{tab_length})+)` — how many whole indent levels the block starts with.
    let indentLevel = 0;
    const step = this.tabLength;
    while (block.startsWith(' '.repeat(step * (indentLevel + 1)))) indentLevel++;

    let level = this.parser.state.isState('list') ? 1 : 0;
    let current = parent;
    while (indentLevel > level) {
      const child = current.length ? current.children[current.length - 1] : null;
      if (child !== null && (LIST_TYPES.indexOf(child.tag) !== -1 || ITEM_TYPES.indexOf(child.tag) !== -1)) {
        if (LIST_TYPES.indexOf(child.tag) !== -1) level += 1;
        current = child;
      } else {
        break;
      }
    }
    return [level, current];
  }
}

