/**
 * Block quotes: lines prefixed with `>` (up to three leading spaces, and one
 * optional space after the marker).
 */

import { BlockProcessor } from './base.mjs';
import { Element } from '../../dom/element.mjs';
import { countLeadingSpaces, strip } from '../../text/scan.mjs';

/** `[ ]{0,3}>[ ]?(.*)` anchored at the start of a line. */
function matchQuoteLine(line) {
  const indent = countLeadingSpaces(line);
  if (indent > 3) return null;
  if (indent >= line.length || line[indent] !== '>') return null;
  let i = indent + 1;
  if (i < line.length && line[i] === ' ') i++;
  return { content: line.slice(i) };
}

export class BlockQuoteProcessor extends BlockProcessor {
  /** `(^|\n)[ ]{0,3}>[ ]?(.*)` — leftmost quote line, as a block offset. */
  search(block) {
    let lineStart = 0;
    for (;;) {
