function atLineEnd(text, i) {
  return i === text.length || text[i] === '\n';
}

function matchTitle(text, i) {
  if (i >= text.length) return null;
  const ch = text[i];
  if (ch === '"' || ch === "'") {
    // `(.*)` is greedy and excludes newlines, so take the last quote on the line.
    let lineEnd = text.indexOf('\n', i);
    if (lineEnd === -1) lineEnd = text.length;
    const close = text.lastIndexOf(ch, lineEnd - 1);
    if (close <= i) return null;
    const end = skipSpacesOnly(text, close + 1);
    if (!atLineEnd(text, end)) return null;
    return { title: text.slice(i + 1, close), end };
  }
  if (ch === '(') {
    let lineEnd = text.indexOf('\n', i);
    if (lineEnd === -1) lineEnd = text.length;
    const close = text.lastIndexOf(')', lineEnd - 1);
    if (close <= i) return null;
    const end = skipSpacesOnly(text, close + 1);
    if (!atLineEnd(text, end)) return null;
    return { title: text.slice(i + 1, close), end };
  }
  return null;
}

function matchDefinitionAt(block, lineStart) {
  let i = lineStart;
  const indent = countLeadingSpaces(block.slice(lineStart, block.indexOf('\n', lineStart) === -1 ? block.length : block.indexOf('\n', lineStart)));
  if (indent > 3) return null;
  i += indent;
  if (block[i] !== '[') return null;
  i++;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i++;
  if (i >= block.length || block[i] !== ']') return null;
  const rawId = block.slice(idStart, i);
  i++;
  if (i >= block.length || block[i] !== ':') return null;
  i++;

  i = skipSpacesOnly(block, i);
  if (i < block.length && block[i] === '\n') i++;
  i = skipSpacesOnly(block, i);

