  if (atLineEnd(block, i)) return { start: lineStart, end: i, id: rawId, link, title: null };
  if (atLineEnd(block, beforeFold)) {
    return { start: lineStart, end: beforeFold, id: rawId, link, title: null };
  }
  return null;
}

export class ReferenceProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let lineStart = 0;
    for (;;) {
      const m = matchDefinitionAt(block, lineStart);
      if (m !== null) {
        const id = strip(m.id).toLowerCase();
        let link = m.link;
        let s = 0;
        while (s < link.length && link[s] === '<') s++;
        let e = link.length;
        while (e > s && link[e - 1] === '>') e--;
        this.parser.md.references.set(id, [link.slice(s, e), m.title]);

        const after = block.slice(m.end);
        const before = block.slice(0, m.start);
        if (strip(after) !== '') {
          let k = 0;
          while (k < after.length && after[k] === '\n') k++;
          blocks.unshift(after.slice(k));
        }
        if (strip(before) !== '') {
          let k = before.length;
          while (k > 0 && before[k - 1] === '\n') k--;
          blocks.unshift(before.slice(0, k));
        }
