/**
 * Fallback processor: anything left over becomes a paragraph. Inside a tight
 * list the text is folded into the list item instead of getting its own `<p>`.
 */

import { BlockProcessor } from './base.mjs';
import { Element, textValue, hasText } from '../../dom/element.mjs';
import { strip, lstrip } from '../../text/scan.mjs';

export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (strip(block) === '') return;

    if (this.parser.state.isState('list')) {
      const sibling = this.lastChild(parent);
      if (sibling !== null) {
        sibling.tail = hasText(sibling.tail)
          ? textValue(sibling.tail) + '\n' + block
          : '\n' + block;
      } else if (hasText(parent.text)) {
        parent.text = textValue(parent.text) + '\n' + block;
      } else {
        parent.text = lstrip(block);
      }
      return;
    }

    const p = new Element('p');
    parent.append(p);
    p.text = lstrip(block);
  }
}

