/**
 * Assembles the block parser with its processors in priority order.
 */

import { BlockParser } from './parser.mjs';
import { EmptyBlockProcessor } from './empty.mjs';
import { ListIndentProcessor } from './listIndent.mjs';
import { CodeBlockProcessor } from './code.mjs';
import { HashHeaderProcessor, SetextHeaderProcessor } from './headers.mjs';
import { HRProcessor } from './hr.mjs';
import { OListProcessor, UListProcessor } from './lists.mjs';
import { BlockQuoteProcessor } from './blockquote.mjs';
import { ReferenceProcessor } from './reference.mjs';
import { ParagraphProcessor } from './paragraph.mjs';

export function buildBlockParser(md) {
  const parser = new BlockParser(md);
  parser.register(new EmptyBlockProcessor(parser), 'empty', 100);
  parser.register(new ListIndentProcessor(parser), 'indent', 90);
  parser.register(new CodeBlockProcessor(parser), 'code', 80);
  parser.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  parser.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  parser.register(new HRProcessor(parser), 'hr', 50);
  parser.register(new OListProcessor(parser), 'olist', 40);
  parser.register(new UListProcessor(parser), 'ulist', 30);
  parser.register(new BlockQuoteProcessor(parser), 'quote', 20);
  parser.register(new ReferenceProcessor(parser), 'reference', 15);
  parser.register(new ParagraphProcessor(parser), 'paragraph', 10);
  return parser;
}

export { BlockParser };

