/**
 * Shared scaffolding for inline processors.
 *
 * Each processor exposes `find(data, from)` — locate the next candidate, in
 * leftmost order — and `handleMatch(match, data)` returning
 * `[node, start, end]`. Returning a null `start`/`end` rejects the candidate and
 * the scan resumes after it.
 */

import { INLINE_PLACEHOLDER_PREFIX, ETX, STX } from '../util.mjs';
import { isDigit } from '../../text/chars.mjs';

export class InlineProcessorBase {
  constructor(md) {
    this.md = md;
  }

  /** Rejected candidate helper. */
  static reject() {
    return [null, null, null];
  }

  /**
   * Expand inline placeholders back into serialized HTML. Used where the
   * matched text becomes an attribute value or raw HTML rather than a subtree.
   */
  unescape(text) {
    const processor = this.md.inlineTreeprocessor;
    if (!processor) return text;
    let out = '';
    let i = 0;
    for (;;) {
      const at = text.indexOf(INLINE_PLACEHOLDER_PREFIX, i);
      if (at === -1) {
        out += text.slice(i);
        return out;
      }
      const parsed = parsePlaceholderAt(text, at);
      if (parsed === null) {
        out += text.slice(i, at + INLINE_PLACEHOLDER_PREFIX.length);
        i = at + INLINE_PLACEHOLDER_PREFIX.length;
        continue;
      }
      const node = processor.stashedNodes.get(parsed.id);
      out += text.slice(i, at);
      if (node !== undefined) {
        out += typeof node === 'string' ? node : this.md.serialize(node);
      }
      i = parsed.end;
    }
  }

  /** Turn `STX<code>ETX` escape placeholders back into `\<char>`. */
  backslashUnescape(text) {
    let out = '';
    let i = 0;
    while (i < text.length) {
      if (text[i] === STX) {
        let j = i + 1;
        while (j < text.length && isDigit(text.charCodeAt(j))) j++;
        if (j > i + 1 && j < text.length && text[j] === ETX) {
          out += '\\' + String.fromCharCode(Number(text.slice(i + 1, j)));
          i = j + 1;
          continue;
        }
      }
      out += text[i];
      i++;
    }
    return out;
  }
}

/** Parse `STX klzzwxh:<digits> ETX` at `at`; returns `{id, end}` or null. */
export function parsePlaceholderAt(text, at) {
  let i = at + INLINE_PLACEHOLDER_PREFIX.length;
  const start = i;
  while (i < text.length && isDigit(text.charCodeAt(i))) i++;
  if (i === start) return null;
  if (i >= text.length || text[i] !== ETX) return null;
  return { id: text.slice(start, i), end: i + 1 };
}

/** Search for a placeholder at or after `index`, mirroring `re.search`. */
export function searchPlaceholder(text, index) {
  let i = index;
  for (;;) {
    const at = text.indexOf(INLINE_PLACEHOLDER_PREFIX, i);
    if (at === -1) return null;
    const parsed = parsePlaceholderAt(text, at);
    if (parsed !== null) return { start: at, id: parsed.id, end: parsed.end };
    i = at + 1;
  }
}

/** Python `$` outside `MULTILINE`: end of string, or before a single final newline. */
export function atStringEnd(data, pos) {
  return pos === data.length || (pos === data.length - 1 && data[pos] === '\n');
}

