/**
 * Code spans and backslash escapes.
 */

import { InlineProcessorBase } from './base.mjs';
import { Element, atomic } from '../../dom/element.mjs';
import { STX, ETX, ESCAPED_CHARS } from '../util.mjs';
import { countRun, countRunBack, strip, replaceAllLiteral } from '../../text/scan.mjs';

const ESCAPED_BSLASH = STX + '92' + ETX;

/**
 * `(?:(?<!\\)((?:\\{2})+)(?=`+)|(?<!\\)(`+)(.+?)(?<!`)\2(?!`))`
 *
 * The first branch protects an even run of backslashes in front of a backtick;
 * the second is the code span itself, matched with the shortest content that
 * lets an equal-length closing run appear.
 */
export class BacktickInlineProcessor extends InlineProcessorBase {
  find(data, from) {
    for (let i = from; i < data.length; i++) {
      const ch = data[i];
      if (ch === '\\') {
        if (i > 0 && data[i - 1] === '\\') continue;
        const run = countRun(data, i, '\\');
        if (run % 2 === 0 && i + run < data.length && data[i + run] === '`') {
          return { start: i, end: i + run, group1: data.slice(i, i + run), group3: null };
        }
        continue;
      }
      if (ch !== '`') continue;
      if (i > 0 && data[i - 1] === '\\') continue;
      const run = countRun(data, i, '`');
      for (let n = run; n >= 1; n--) {
        const fence = '`'.repeat(n);
        const contentStart = i + n;
        for (let close = contentStart + 1; close + n <= data.length; close++) {
          if (!data.startsWith(fence, close)) continue;
          if (data[close - 1] === '`') continue;
          if (close + n < data.length && data[close + n] === '`') continue;
          return {
            start: i,
            end: close + n,
            group1: null,
            group3: data.slice(contentStart, close),
          };
        }
      }
    }
    return null;
  }

  handleMatch(match) {
    if (match.group3 !== null) {
      const el = new Element('code');
      el.text = atomic(strip(match.group3));
      return [el, match.start, match.end];
    }
    return [replaceAllLiteral(match.group1, '\\\\', ESCAPED_BSLASH), match.start, match.end];
  }
}

/**
 * `\\(.)` with `DOTALL`. Escapable characters are replaced by a sentinel that
 * survives inline processing and is restored just before serialization.
 */
export class EscapeInlineProcessor extends InlineProcessorBase {
  find(data, from) {
    for (let i = from; i + 1 < data.length; i++) {
      if (data[i] === '\\') return { start: i, end: i + 2, char: data[i + 1] };
    }
    return null;
  }

  handleMatch(match) {
    if (ESCAPED_CHARS.indexOf(match.char) !== -1) {
      return [STX + match.char.charCodeAt(0) + ETX, match.start, match.end];
    }
    return [null, match.start, match.end];
  }
}

export { countRunBack };

